package ama.transcript;
import java.util.*;import ama.storage.*;import ama.task.*;import static org.junit.jupiter.api.Assertions.*;
/** Full real resubmit with independently constructed production runtime; each final transaction rolls back. */
public final class Task11Fix02ReplacementBudgetProbe {
 private static final ThreadLocal<Map<String,Object>> LAST=ThreadLocal.withInitial(Map::of);
 public static Map<String,Object> lastAttempt(){return LAST.get();}
 static final String[] DIM={"utf8","scalars","utf16","copyBytes","copyUtf16","maxFactRows","maxFactEdges","responseBytes"};
 public interface Snapshot {Map<String,String> read()throws Exception;}
 public interface Telemetry {List<Map<String,Object>> read()throws Exception;}
 public static Map<String,Object> verify(JdbcPublicationService base,ama.contract.IdentityContracts.Actor actor,String meeting,String publication,FileBackendCatalog backends,Task11Fix02FinalGateGuard guard,Snapshot snapshots,Telemetry telemetry,java.util.function.Consumer<Map<String,Object>> progress)throws Exception{
  assertEquals(2,base.j.queryForObject("SELECT COUNT(*) FROM external_execution e JOIN publication_submission s ON s.task_id=e.task_id WHERE s.publication_id=? AND e.state='FAILED' AND e.no_effect_basis='DEFINITIVE_REJECTION'",Integer.class,publication));
  var evidence=new ArrayList<Map<String,Object>>();var normal=run(base,actor,meeting,publication,backends,guard,snapshots,telemetry,-1,0,"normal-before");assertEquals("FINAL_GATE",normal.get("result"));assertEquals(2L,normal.get("gets"));assertEquals(1L,normal.get("posts"));evidence.add(normal);progress.accept(normal);
  var l=base.limits;long[] maxima={l.utf8(),l.scalars(),l.utf16(),l.copyBytes(),l.copyUtf16(),base.authority.readBudget().maxFactRows(),base.authority.readBudget().maxFactEdges(),l.responseBytes()};
  for(int d=0;d<8;d++){
   long low=0,high=maxima[d];boolean covered=false;
   int maximumTrials=d==7?26:12;for(int trial=1;trial<=maximumTrials&&high-low>1;trial++){
    long value=low+(high-low)/2;var result=run(base,actor,meeting,publication,backends,guard,snapshots,telemetry,d,value,DIM[d]+"-"+trial);evidence.add(result);progress.accept(result);
    String code=(String)result.get("result");long gets=(Long)result.get("gets"),posts=(Long)result.get("posts");boolean finalEntry=(Boolean)result.get("rollbackBeforeFirstWrite");
    boolean target=code.equals("BUDGET_EXCEEDED")&&gets==2&&posts==1&&finalEntry&&(d!=7||Boolean.TRUE.equals(result.get("completeThreeHttp200")));
    if(target){covered=true;break;}if(code.equals("FINAL_GATE"))high=value;else{assertTrue(Set.of("BUDGET_EXCEEDED","PROVIDER_UNAVAILABLE").contains(code),"Unexpected error cannot calibrate budget");low=value;}
   }
   assertTrue(covered,"Target not reached within"+maximumTrials+" bounded calls for "+DIM[d]+"; early denial is NOT COVERED");var control=run(base,actor,meeting,publication,backends,guard,snapshots,telemetry,-1,0,"normal-after-"+DIM[d]);assertEquals("FINAL_GATE",control.get("result"));assertEquals(2L,control.get("gets"));assertEquals(1L,control.get("posts"));evidence.add(control);progress.accept(control);
  }
  return Map.of("calls",evidence,"maxCalls",119,"dimensions",List.of(DIM),"qualification","Each call invokes actual resubmit end-to-end with fresh real authority/service/queue/outbox. Normal controls reach final submission INSERT after S, both real proof GETs, fresh F and engine. Every write transaction is rollback-only before first write. All eight negative dimensions require exact BUDGET_EXCEEDED after final transaction entry plus both proof GETs and destination POST. Response also requires complete HTTP200 telemetry for all three real responses; it proves response-ledger cumulative F admission, not a network-body-admission-specific negative. Actual last SQL and guard write sequence qualify the specific final-stage consumer, not all final consumers. Earlier failures are calibration only, never coverage. No publication POST/claim.");
 }
 public static Map<String,Object> verifyDimension(JdbcPublicationService base,ama.contract.IdentityContracts.Actor actor,String meeting,String publication,FileBackendCatalog backends,Task11Fix02FinalGateGuard guard,Snapshot snapshots,Telemetry telemetry,java.util.function.Consumer<Map<String,Object>> progress,int dimension,long fixedLimit)throws Exception{
  assertTrue(dimension>=0&&dimension<8);var evidence=new ArrayList<Map<String,Object>>();var before=run(base,actor,meeting,publication,backends,guard,snapshots,telemetry,-1,0,"normal-before-"+DIM[dimension]);assertEquals("FINAL_GATE",before.get("result"));assertEquals(2L,before.get("gets"));assertEquals(1L,before.get("posts"));evidence.add(before);progress.accept(before);
  var l=base.limits;long[] maxima={l.utf8(),l.scalars(),l.utf16(),l.copyBytes(),l.copyUtf16(),base.authority.readBudget().maxFactRows(),base.authority.readBudget().maxFactEdges(),l.responseBytes()};long low=0,high=maxima[dimension];int maximum=fixedLimit>0?1:dimension==7?26:12;boolean covered=false;
  for(int trial=1;trial<=maximum&&high-low>1;trial++){long limit=fixedLimit>0?fixedLimit:low+(high-low)/2;var r=run(base,actor,meeting,publication,backends,guard,snapshots,telemetry,dimension,limit,DIM[dimension]+"-slice-"+trial);evidence.add(r);progress.accept(r);String code=(String)r.get("result");boolean target=code.equals("BUDGET_EXCEEDED")&&(Long)r.get("gets")==2L&&(Long)r.get("posts")==1L&&(Boolean)r.get("rollbackBeforeFirstWrite")&&(dimension!=7||Boolean.TRUE.equals(r.get("completeThreeHttp200")));if(target){covered=true;break;}if(code.equals("FINAL_GATE"))high=limit;else{assertTrue(Set.of("BUDGET_EXCEEDED","PROVIDER_UNAVAILABLE").contains(code));low=limit;}}
  assertTrue(covered,"Required F budget consumer not reached; earlier errors are NOT COVERED");var after=run(base,actor,meeting,publication,backends,guard,snapshots,telemetry,-1,0,"normal-after-"+DIM[dimension]);assertEquals("FINAL_GATE",after.get("result"));assertEquals(2L,after.get("gets"));assertEquals(1L,after.get("posts"));evidence.add(after);progress.accept(after);return Map.of("dimension",DIM[dimension],"dimensionIndex",dimension,"fixedLimit",fixedLimit,"calls",evidence,"complete",true,"qualification","Fresh-JVM full resubmit normal/F-budget-denial/normal; all original tables restored. Response uses F cumulative admission, not network-body-only boundary. No new final/accept/claim/marker/publication POST.");
 }
 static Map<String,Object> run(JdbcPublicationService base,ama.contract.IdentityContracts.Actor actor,String meeting,String publication,FileBackendCatalog backends,Task11Fix02FinalGateGuard guard,Snapshot snapshots,Telemetry telemetry,int dimension,long limit,String label)throws Exception{
  var before=snapshots.read();int eventBefore=telemetry.read().size();long getBefore=base.traffic().get("getWriteAttempts"),postBefore=base.traffic().get("postWriteAttempts");String result;LAST.set(Map.of("label",label,"phase","STARTED"));long started=System.nanoTime();long[]finished={0};guard.arm(meeting,publication);
  try{var service=runtime(base,backends,dimension,limit);long revision=base.j.queryForObject("SELECT revision FROM meeting WHERE id=?",Long.class,meeting),pubRevision=base.j.queryForObject("SELECT revision FROM publication WHERE id=?",Long.class,publication);String confirmation=base.j.queryForObject("SELECT final_confirmation_id FROM meeting WHERE id=?",String.class,meeting);service.resubmit(actor,meeting,publication,"fix02-budget-"+label,revision,pubRevision,confirmation,"CONTROLLED_KNOWLEDGE_V1","controlled-library","controlled-root",UUID.randomUUID().toString());throw new AssertionError("No rollback control may return acceptance");}
  catch(Task11Fix02FinalGateGuard.FinalGateReached reached){assertTrue(guard.finalReached&&guard.rollbackArmed);result="FINAL_GATE";}
  catch(ama.contract.MinutesContracts.Failure failed){assertEquals(ama.contract.MinutesContracts.FailureCode.BUDGET_EXCEEDED,failed.code());result=failed.code().name();}
  catch(java.io.IOException failed){assertEquals("PROVIDER_UNAVAILABLE",failed.getMessage());result=failed.getMessage();}
  finally{finished[0]=System.nanoTime();guard.disarm();assertEquals(before,snapshots.read(),"Every command/task/attempt/operation/execution/submission/publication/meeting/audit/outbox row restored");}
  long elapsed=finished[0]-started;LAST.set(Map.of("label",label,"result",result,"gets",base.traffic().get("getWriteAttempts")-getBefore,"posts",base.traffic().get("postWriteAttempts")-postBefore,"elapsedNs",elapsed,"guard",guard.evidence(),"preimageHashes",before,"preimageRestored",true,"phase","BEFORE_TELEMETRY"));assertTrue(elapsed<java.util.concurrent.TimeUnit.SECONDS.toNanos(25),"Budget result near30s deadline is not dimension evidence");var events=telemetry.read();assertTrue(events.size()>=eventBefore);var observed=List.copyOf(events.subList(eventBefore,events.size()));var empty=observed.stream().filter(e->"EMPTY_PRE_REQUEST_CLOSE".equals(e.get("kind"))).toList();var actual=observed.stream().filter(e->!"EMPTY_PRE_REQUEST_CLOSE".equals(e.get("kind"))).toList();for(var e:empty){assertEquals("HEADER",e.get("phase"));assertEquals(0,((Number)e.get("headerBytes")).intValue());assertEquals(0,((Number)e.get("bodyBytes")).intValue());assertEquals(false,e.get("upstreamConnected"));}if(!empty.isEmpty()){assertEquals(1,empty.size());assertEquals("PROVIDER_UNAVAILABLE",result);assertFalse(guard.rollbackArmed);assertTrue(actual.size()<3,"Early close cannot qualify a normal or final budget target");}long total=0;boolean complete=actual.size()==3;var getPaths=new HashSet<String>();for(var e:actual){assertTrue(Boolean.TRUE.equals(e.get("upstreamComplete"))&&Boolean.TRUE.equals(e.get("forwarded")));assertEquals(((Number)e.get("contentLength")).longValue(),((Number)e.get("receivedBodyBytes")).longValue());total+=((Number)e.get("contentLength")).longValue();complete&=((Number)e.get("status")).intValue()==200;if("GET".equals(e.get("method")))getPaths.add((String)e.get("path"));}complete&=getPaths.size()==2&&actual.size()==3&&"POST".equals(actual.getLast().get("method"));if(result.equals("FINAL_GATE")||guard.rollbackArmed){assertTrue(complete,"Normal and F target require exactly three successful complete HTTP events");assertTrue(empty.isEmpty(),"No early-close event may qualify normal or F target");}var out=new LinkedHashMap<String,Object>();out.put("startedMonotonicNs",started);out.put("finishedMonotonicNs",finished[0]);out.put("elapsedNs",elapsed);out.put("productionLedgerDeadlineNs",30000000000L);out.put("maximumQualifiedElapsedNs",25000000000L);out.put("emptyPreRequestCloses",empty);out.put("httpMetadata",actual);out.put("completeThreeHttp200",complete);out.put("totalResponseBodyBytes",total);out.put("label",label);out.put("dimension",dimension<0?"normal":DIM[dimension]);out.put("limit",limit);out.put("result",result);out.put("gets",base.traffic().get("getWriteAttempts")-getBefore);out.put("posts",base.traffic().get("postWriteAttempts")-postBefore);out.putAll(guard.evidence());out.put("preimageHashes",before);out.put("preimageRestored",true);return Map.copyOf(out);
 }
 static JdbcPublicationService runtime(JdbcPublicationService base,FileBackendCatalog backends,int dimension,long limit)throws Exception{
  var a=base.authority;var l=base.limits;var archive=a.readBudget();long[]v={l.utf8(),l.scalars(),l.utf16(),l.copyBytes(),l.copyUtf16(),l.responseBytes()};if(dimension>=0&&dimension<5)v[dimension]=limit;else if(dimension==7)v[5]=limit;else if(dimension==5||dimension==6)archive=Task11Fix02DistinctLedgerProbe.replace(archive,DIM[dimension],limit);
  var limits=new TranscriptAcquisitionBudget(v[0],v[1],v[2],v[3],v[4],v[5],l.revisionDepth(),l.revisionNodes(),l.tasks());var parts=JdbcTranscriptAuthority.create(a.dataSource(),a.transactionRunner(),a.savedAccess(),new TranscriptFilePurposePolicy(),backends,Map.of(),archive,a.canonicalBudget());var authority=parts.authority();var outbox=new JdbcOutbox(a.dataSource(),new MinutesEventReferences(a.dataSource()).validators());var queue=new JdbcTaskQueue(a.dataSource(),new JdbcSubjectFences(a.dataSource(),Set.of("MEETING")),outbox,Map.of("KNOWLEDGE_PUBLISH_V1",authority.publicationDomain()));var saved=new JdbcSavedTranscripts(authority,base.archives,limits,base.transcripts.correctionFor(a));return new JdbcPublicationService(authority,base.archives,base.pin,limits,saved,queue,outbox,base.client);
 }
}
